use std :: fs ; use std :: io :: { BufRead , BufReader } ; use std :: path :: PathBuf ; use std :: process :: Stdio ; use anyhow :: { Context , Result } ; use clap :: CommandFactory ; use clap_complete :: generate ; use clap_complete :: shells :: Zsh ; use include_dir :: { Dir , include_dir } ; use crate :: cli :: Cli ; use std :: io :: Write ; use std :: sync :: { LazyLock , Mutex } ; use super :: * ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; use tempfile :: TempDir ; # [doc = " Parses the file content to find and validate marker positions"] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `lines` - The lines of the file to parse"] # [doc = " * `start_marker` - The start marker to look for"] # [doc = " * `end_marker` - The end marker to look for"] fn parse_markers (lines : & [String] , start_marker : & str , end_marker : & str) -> MarkerState { let start_idx = lines . iter () . position (| line | line . trim () == start_marker) ; let end_idx = lines . iter () . position (| line | line . trim () == end_marker) ; match (start_idx , end_idx) { (Some (start) , Some (end)) if start < end => MarkerState :: Valid { start , end } , (None , None) => MarkerState :: NotFound , (start , end) => MarkerState :: Invalid { start , end } , } }